"""Complete French chicken and Danish tongue dishes with all sauce components."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r
def eggs(a):return I('eggs',a,'','large eggs for hard boiling','Use large pasteurized shell eggs if preferred; cook until the yolks are firm.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up to cover as directed.')
def boil():return ['Put {{eggs}} in a saucepan with {{water}}, adding more water only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout.']
END='Keep covered at 4°C (40°F) or colder until serving. Refrigerate leftovers within 2 hours and use within 2 days. Do not leave the platter at room temperature for more than 2 hours.'
REF=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Variety meats: https://ask.fsis.usda.gov/article/What-are-the-recommended-cooking-times-for-veal .'
def finish(r):r['category']='Main dishes';r['source']+=REF;return eggsource(r)

r=add(32,'Poulets en Mayonnaise — Cold Chicken in Herb Jelly Sauce',8,300,'Lemon-braised chicken is coated with a chilled velouté-and-jelly sauce flavored with parsley and tarragon, then garnished with aspic and crisp croutons.',[
 I('chickens',2,'','small oven-ready chickens, about 1.2 kg each, giblets removed','Use chickens of a similar total weight; larger birds need longer cooking.'),I('chickenbutter',60,'g','unsalted butter, softened','Use the same weight of a block-style dairy-free butter alternative.'),I('chickensalt',6,'g','fine salt for the chicken','Reduce or omit.'),I('chickenpepper',.25,'tsp','coarsely ground black pepper','Use the same amount of white pepper.'),I('chickenjuice',30,'ml','lemon juice for the chicken','Use the same volume of lime juice for a different flavor.'),I('slicelemon',1,'','lemon, washed and thinly sliced','Use one small lime for a different flavor.'),I('barding',120,'g','thin slices of unsmoked pork back fat for barding','Use the same weight of unsmoked streaky bacon; reduce added salt if the bacon is salty.'),I('carrot',150,'g','carrot, peeled and sliced','Use the same weight of parsnip for a sweeter broth.'),I('onion',150,'g','onion, peeled and sliced','Use the same weight of shallots.'),I('thyme',2,'g','fresh thyme sprigs','Use 0.5 g dried thyme.'),I('bay',1,'','dried bay leaf','Omit if unavailable.'),I('braiseparsley',10,'g','fresh parsley sprigs','Use the same weight of chervil sprigs.'),I('braisestock',750,'ml','unsalted prepared chicken stock for braising','Use the same volume of unsalted prepared vegetable stock.'),
 I('jellystock',360,'ml','unsalted prepared chicken stock for aspic','Use the same volume of unsalted prepared veal stock.'),I('gelatin',10,'g','unflavored powdered gelatin','Use equivalent-strength leaf gelatin according to its package.'),water(40,'bloomwater'),I('saucebutter',20,'g','unsalted butter for the velouté','Use the same weight of a block-style dairy-free butter alternative.'),I('flour',20,'g','plain flour','Use the same weight of a plain gluten-free flour blend suitable for sauces.'),I('mushrooms',60,'g','white mushrooms, cleaned and finely chopped','Use the same weight of cremini mushrooms; the sauce will be darker.'),I('saucestock',400,'ml','unsalted prepared chicken stock for the velouté','Use the same volume of unsalted prepared veal stock.'),vinegar(30,'tarragon'),pepper(.25),salt(.5),I('parsley',5,'g','fresh parsley leaves, finely chopped','Use the same weight of chervil.'),I('tarragon',3,'g','fresh tarragon leaves, finely chopped','Use 1 g dried tarragon.'),I('bread',100,'g','day-old white bread, cut into small cubes','Use the same weight of gluten-free bread.'),I('toastbutter',15,'g','unsalted butter for croutons','Use the same weight of olive oil.')],
 ['Heat the oven to 170°C (340°F). Pat {{chickens}} dry without rinsing. Mix {{chickenbutter}}, {{chickensalt}}, {{chickenpepper}} and {{chickenjuice}}, then spread inside the cavities. Loosely tie the legs with kitchen string.','Put {{carrot}}, {{onion}}, {{thyme}}, {{bay}} and {{braiseparsley}} in a large lidded roasting dish. Lay half of {{barding}} over the vegetables. Set the birds on top, cover their breasts with {{slicelemon}} and the remaining barding fat, and pour {{braisestock}} around them.','Cover and braise for about 1½–2 hours, checking that liquid remains and adding a little hot water if needed. Check each bird: the thickest breast and inner thigh must reach 74°C (165°F), with the thermometer clear of bone.','Remove the birds, discard the string and rest for 10 minutes. Remove the barding fat and lemon slices, carve into serving pieces and remove loose bones. Spread in shallow containers and refrigerate promptly, within 2 hours of cooking, until cold, about 1–1½ hours. The braising vegetables, fat and liquid are not needed in the measured sauce.','While the birds cook, sprinkle {{gelatin}} over cold {{bloomwater}} and leave for 5 minutes. Heat {{jellystock}} until steaming, remove from heat and dissolve the bloomed gelatin in it. Pour into a shallow container and refrigerate for at least 2 hours until set. Divide the finished aspic into two equal portions; keep one chilled for garnish.','For the velouté, melt {{saucebutter}} in a saucepan. Add {{mushrooms}} and cook gently for 3 minutes without browning. Stir in {{flour}} for 1 minute, then gradually whisk in {{saucestock}}. Simmer for 8 minutes, stirring. Press through a fine sieve, discarding the mushroom pieces. Return the sauce to the pan.','Add the other half of the aspic to the velouté with {{vinegar}} and {{pepper}}. Heat gently until the jelly melts. Mark the sauce level on a wooden spoon, then simmer uncovered, stirring frequently, until reduced by about one third, about 10–15 minutes.','Stir in {{parsley}}, {{tarragon}} and {{salt}} and simmer for 1 minute. Transfer the sauce to a bowl set over ice water, keeping water out, and stir frequently until cool and beginning to thicken but still pourable, about 15–20 minutes.','Arrange the cold chicken on a platter, spoon the cool thickening sauce over the pieces and refrigerate for at least 30 minutes until the coating has set. Cut the reserved aspic into small cubes.','For the garnish, melt {{toastbutter}} in a frying pan, add {{bread}} and cook over medium heat for 5–8 minutes, turning, until golden and crisp. Cool on a plate. Garnish the chicken with the aspic cubes and croutons just before serving.',END],
 'The complete chicken, velouté, jelly and crouton references are expanded. The same book’s Chapon poêlé explicitly permits carrots, onion, thyme, bay, parsley and broth when prepared poêle is unavailable; this is used as a measured shortcut. Chicken size and all missing weights are modern working quantities. Eight skimming ladles of velouté to four of jelly become approximately 400 ml sauce to 200 ml aspic, based on an explicit modern 50 ml ladle, not a verified historical conversion. Prepared stock plus gelatin replaces making meat jelly from bones. Mushroom stock-and-roux velouté replaces the longer meat-stock preparation. The sauce is reduced separately and cooled before coating the cold chicken; this resolves the source’s conflicting hot-casserole and cold-piece wording. Total time includes concurrent braising, jelly setting and chilling.');r['category']='Main dishes';r['source']+=REF
vi=copy.deepcopy(r['ingredients'])+[I('liaisonegg',1,'','large egg for the optional sauce liaison','Use 50 g pasteurized liquid whole egg.')];vs=copy.deepcopy(r['steps']);vs[7]='Beat {{liaisonegg}} in a heatproof bowl. Remove the reduced sauce from the heat and gradually whisk a few spoonfuls into the egg. Return everything to the pan with {{parsley}}, {{tarragon}} and {{salt}}. Stir over low heat until the sauce reaches 71°C (160°F) throughout, without boiling. Transfer to a bowl over ice water and stir until cool and starting to thicken, about 15–20 minutes, keeping water out.';variant(r,'egg-liaison','With an egg-thickened sauce',vi,vs);r['notes']+=' The original optional liaison says one egg, not specifically one yolk. Its full-egg variation is retained; controlled heating replaces boiling after adding the egg.'

TONGUE_ITEMS=[I('tongues',5,'','small fresh calf tongues, about 400–500 g each, cleaned by the butcher','Use the same total weight of larger calf tongues; simmer longer until tender.'),water(3500,'poachwater'),I('poachsalt',15,'g','salt for the cooking water','Reduce or omit.'),I('coatingeggs',2,'','large eggs, beaten, for coating','Use 100 g pasteurized liquid whole egg.'),I('crumbs',150,'g','fine dry breadcrumbs','Use the same weight of gluten-free breadcrumbs.'),I('frybutter',100,'g','butter for shallow frying','Use the same weight of clarified butter.'),I('garnish',10,'g','fresh parsley leaves, washed and dried','Use the same weight of chervil leaves.')]
TONGUE_STEPS=['Put {{tongues}} in a large pot with {{poachwater}} and {{poachsalt}}, adding more water only if needed to cover. Bring to a boil, skim, then simmer gently for about 2–3 hours until a skewer enters easily and the center reaches at least 71°C (160°F). Top up with hot water if needed.','Lift out one tongue at a time. When cool enough to handle but still warm, peel off the thick outer skin and trim any tough tissue at the base. Split each tongue lengthwise into two or three pieces. If preparing ahead, spread in shallow containers and refrigerate promptly within 2 hours; use within 2 days.','Put {{coatingeggs}} and {{crumbs}} in separate shallow dishes. Dip the tongue pieces in egg, then breadcrumbs, pressing to coat. Discard any coating egg or crumbs left after dipping.','Heat {{frybutter}} in a large frying pan over medium heat. Fry the pieces in batches for about 3–5 minutes per side until golden and hot throughout, dividing the measured butter among the batches. If the tongue was chilled, reheat the center to 74°C (165°F). Do not let the butter burn.']
MAYO_ITEMS=[yolks(2),oil(250),vinegar(30,'tarragon'),salt(.5),I('whitepepper',.125,'tsp','ground white pepper','Use the same amount of black pepper.'),I('pickles',50,'g','sweet-sour pickled cucumber, drained and finely chopped','Use the same weight of drained cornichons; the flavor will be sharper.'),I('mustard',15,'ml','prepared smooth mustard','Use the same volume of Dijon mustard.')]
